{
  "headline": "Kubernetes Resource Request Verdicts for explainer-lab",
  "cpu": {
    "decision": "decrease_ok",
    "explanation": "The CPU request can be decreased from 0.500 cores to 0.010 cores. The candidate request of 0.000 cores is below the minimum floor of 0.010 cores, so the minimum is used instead."
  },
  "memory": {
    "decision": "decrease_ok",
    "explanation": "The memory request can be decreased from 512Mi to 32Mi. The candidate request of 25Mi is below the minimum floor of 32Mi, so the minimum is used instead."
  },
  "caveats": [
    "Workload name is inferred from the pod name.",
    "Revisions are not tracked, so samples from different releases are mixed.",
    "Usage figures are the highest value across pods (conservative).",
    "p50/p95/max use a 5-minute CPU rate; peak_1m uses a 1-minute rate and is still limited by the scrape interval.",
    "No latency, error-rate or SLO data is included.",
    "History covers about 4.7 h of the requested 6.0 h window.",
    "CPU throttling ratio unavailable: no CPU limit is enforced, or the cAdvisor throttling metrics are missing."
  ]
}
